      "kind": "acceptance",
      "cwd": "."
    },
240→    {
      "id": "V3",
      "cmd": "env APP_ENV=testing DB_CONNECTION=sqlite DB_DATABASE=:memory: ../../scripts/php84 vendor/bin/pest --ci tests/Http tests/Arch tests/Observability tests/Feature",
      "expect": "exit0; drive не задет удалением легаси карт",
