            if ($operation !== null) {
                $this->metrics->histogram(
                    name: 'vaulter_http_request_duration_seconds',
                    value: (hrtime(true) - $started) / 1_000_000_000,
                    labels: [
                        'operation' => $operation,
                        'tier' => LoadTier::label(),
                        'outcome' => $outcome,
                    ],
