    {
        $name = $request->route()?->getName();

        return is_string($name) ? VaulterHttpOperationMap::operationFor($name) : null;
    }

    private function outcomeFor(int $status): string
    {
        if ($status >= 500) {
            return 'server_error';
        }

        if ($status >= 400) {
            return 'client_error';
        }

        return 'success';
    }
