    $retry = $this->putJson(Docs::url('documents/'.$id.'/content'), ['content' => Docs::doc('Clobber')], ['If-Match' => $rebuilt]);
    $text = $retry->json('data.content.content.0.content.0.text');
    fwrite(STDERR, "retry status=".$retry->status()." text=".json_encode($text)." etag=".$retry->headers->get('ETag')."\n");
    fwrite(STDERR, "stored=".json_encode(Hub::aggregate($node)->content['content'][0]['content'][0]['text'] ?? null)."\n");

    expect($rejected->status())->toBe(412)
        ->and($rejected->json('meta.context.actual'))->toBeNull()
        ->and($rebuilt)->not->toBe($current);
});

