    fwrite(STDERR, "archived missing=".$missing->status()." ".$missing->json('code')."\n");
    fwrite(STDERR, "archived stale=".$stale->status()." ".$stale->json('code')." actual=".json_encode($stale->json('meta.context.actual'))."\n");
    fwrite(STDERR, "archived fresh=".$fresh->status()." ".$fresh->json('code')."\n");
    fwrite(STDERR, "stored=".json_encode(Hub::aggregate($node)->content['content'][0]['content'][0]['text'] ?? null)."\n");

