    fwrite(STDERR, "unknown ".$unknown->status()." ".json_encode(Docs::problemWithoutRequestId($unknown))."\n");
    expect(Docs::problemWithoutRequestId($hidden))->toBe(Docs::problemWithoutRequestId($unknown));
});

it('prints 304 conditional headers', function (): void {
